mapper.select:
SELECT t.pk_id, t.id, t.tenant_id, t.people_id, t.plan_id, t.plan_version_id, t.task_code, t.title, t.category, t.frequency, t.time_slot, t.related_ref, t.enabled, t.sort_order, t.payload_json, t.is_deleted, t.gmt_created, t.gmt_modified, t.gmt_deleted FROM care_plan_task t INNER JOIN care_plan p ON p.id = t.plan_id AND p.is_deleted = 0 WHERE t.tenant_id = #{tenantId} AND t.is_deleted = 0 AND t.enabled = 1 AND p.status = 'ACTIVE' AND p.current_version_id = t.plan_version_id AND t.people_id IN
#{pid}
ORDER BY t.people_id ASC, t.sort_order ASC, t.gmt_created ASC
